package localchat;
import java.nio.file.*;import java.nio.file.attribute.*;import java.util.*;import java.util.concurrent.atomic.*;
/** Synthetic local copy/resume/hash/permission tests; never connects to a server. */
public final class CopyResumeTest {
 static int checks;static void check(boolean value,String name){checks++;if(!value)throw new AssertionError(name);}
 static Tools tools(Path root,Path secret,boolean approve,Tools.Permission permission){return new Tools(new Tools.Context(root,root.resolve("skills"),root.resolve("rules.md"),secret,Map.of(),null,new Mcp(),PathMap.none(),approve,EnumSet.noneOf(Tools.Access.class),permission),List.of());}
 static Tools.Result copy(Tools t,Path from,Path to,boolean overwrite){return t.execute(new ChatClient.ToolCall("copy","copy_path",Json.obj("source",from.toString(),"destination",to.toString(),"overwrite",overwrite)));}
 static String digest(Path file)throws Exception{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file)));}
 public static void main(String[] args)throws Exception{
  Path root=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"copy-");Path secret=root.resolve("settings.properties");Files.writeString(secret,"synthetic setting");Tools t=tools(root,secret,true,(a,b)->Tools.Decision.NO);
  Path source=root.resolve("drawing.pdf"),container=Files.createDirectories(root.resolve("drawings")),target=container.resolve("drawing.pdf");Files.write(source,new byte[]{0,1,2,3,4,5});var copied=copy(t,source,container,false);check(!copied.isError&&digest(source).equals(digest(target)),"new file copy has equal SHA-256");check(copied.text.contains("SHA-256"),"copy result reports verification");
  FileTime original=FileTime.fromMillis(1234567890000L);Files.setLastModifiedTime(target,original);var repeated=copy(t,source,container,false);check(!repeated.isError&&repeated.text.contains("identic"),"identical existing file is successful without overwrite");check(Files.getLastModifiedTime(target).equals(original),"identical target is not rewritten");check(!copy(t,source,source,false).isError,"same source and target file is idempotent");
  Files.writeString(target,"different");var conflict=copy(t,source,container,false);check(conflict.isError&&Files.readString(target).equals("different"),"different target conflict preserves existing file");check(Files.exists(source),"copy conflict preserves source");check(!copy(t,source,container,true).isError&&digest(target).equals(digest(source)),"explicit overwrite is hash verified");
  Path tree=Files.createDirectories(root.resolve("source-tree"));Files.writeString(tree.resolve("existing.pdf"),"same drawing");Files.createDirectories(tree.resolve("nested"));Files.writeString(tree.resolve("nested/new.pdf"),"new drawing");Path treeContainer=Files.createDirectories(root.resolve("tree-destination")),partial=Files.createDirectories(treeContainer.resolve("source-tree"));Files.writeString(partial.resolve("existing.pdf"),"same drawing");Files.writeString(partial.resolve("extra.pdf"),"unrelated retained");Files.setLastModifiedTime(partial.resolve("existing.pdf"),original);
  var resumed=copy(t,tree,treeContainer,false);check(!resumed.isError&&Files.readString(partial.resolve("nested/new.pdf")).equals("new drawing"),"partial folder resumes and fills missing drawings");check(Files.getLastModifiedTime(partial.resolve("existing.pdf")).equals(original),"folder resume does not recopy matching drawing");check(Files.readString(partial.resolve("extra.pdf")).equals("unrelated retained"),"folder resume preserves unmentioned destination files");check(resumed.text.contains("SHA-256")&&resumed.text.contains("1"),"folder result distinguishes copied and skipped");check(!copy(t,tree,treeContainer,false).isError,"complete folder retry also succeeds");
  Files.writeString(partial.resolve("existing.pdf"),"conflicting drawing");Files.writeString(tree.resolve("later.pdf"),"later");var treeConflict=copy(t,tree,treeContainer,false);check(treeConflict.isError&&!Files.exists(partial.resolve("later.pdf")),"folder conflicts detected before any new copy");check(Files.readString(partial.resolve("existing.pdf")).equals("conflicting drawing"),"folder conflict never authorizes overwrite");
  var readOnly=tools(root,secret,true,(a,b)->{throw new AssertionError("readOnly must not prompt");}).readOnly(true);check(copy(readOnly,source,target,false).isError,"readOnly blocks even idempotent copy");AtomicInteger asks=new AtomicInteger();var denied=tools(root,secret,false,(a,b)->{asks.incrementAndGet();return Tools.Decision.NO;});check(copy(denied,source,root.resolve("denied.pdf"),false).isError&&!Files.exists(root.resolve("denied.pdf"))&&asks.get()==1,"denial preserves destination and remains one approval");
  check(copy(t,secret,root.resolve("leak.txt"),false).isError&&!Files.exists(root.resolve("leak.txt")),"direct protected source refused");Path holder=Files.createDirectories(root.resolve("protected-source")),nestedSecret=holder.resolve("settings.properties");Files.writeString(nestedSecret,"synthetic protected");var treeProtection=tools(root,nestedSecret,true,(a,b)->Tools.Decision.NO);check(copy(treeProtection,holder,root.resolve("protected-copy"),false).isError&&!Files.exists(root.resolve("protected-copy")),"nested protected source detected before directory copy");
  Path alternate=Files.createDirectories(root.resolve("alternate")),named=alternate.resolve("settings.properties");Files.writeString(named,"replacement");check(copy(t,named,root,true).isError&&Files.readString(secret).equals("synthetic setting"),"resolved destination filename cannot overwrite protected settings");
  Path linked=root.resolve("settings-hardlink");Files.createLink(linked,secret);check(copy(t,linked,root.resolve("hardlink-copy"),false).isError&&!Files.exists(root.resolve("hardlink-copy")),"protected source hardlink alias refused");
  AtomicReference<Tools> cancelling=new AtomicReference<>();cancelling.set(tools(root,secret,false,(a,b)->{cancelling.get().cancel();return Tools.Decision.YES;}));var cancelled=copy(cancelling.get(),tree,root.resolve("cancelled-copy"),false);check(cancelled.isError&&!Files.exists(root.resolve("cancelled-copy")),"cancelled traversal does not report completed folder or create target");
  Tools alreadyCancelled=tools(root,secret,true,(a,b)->Tools.Decision.NO);alreadyCancelled.cancel();check(copy(alreadyCancelled,source,root.resolve("cancelled-file"),false).isError&&!Files.exists(root.resolve("cancelled-file")),"pre-cancelled file copy cannot execute");
  for(Tools.Decision decision:List.of(Tools.Decision.YES,Tools.Decision.ALWAYS))for(String operation:List.of("make_dir","write_file","copy_path")){
   Path late=root.resolve("late-"+decision+"-"+operation);var grants=EnumSet.noneOf(Tools.Access.class);AtomicReference<Tools> delayed=new AtomicReference<>();
   delayed.set(new Tools(new Tools.Context(root,root.resolve("skills"),root.resolve("rules.md"),secret,Map.of(),null,new Mcp(),PathMap.none(),false,grants,(a,b)->{delayed.get().cancel();return decision;}),List.of()));
   Map<String,Object> arguments=operation.equals("copy_path")?Json.obj("source",source.toString(),"destination",late.toString()):Json.obj("path",late.toString(),"content","must not be written");
   var stopped=delayed.get().execute(new ChatClient.ToolCall("late",operation,arguments));check(stopped.isError&&!Files.exists(late),"Stop while awaiting "+decision+" prevents "+operation);
   check(grants.isEmpty(),"late "+decision+" cannot persist permission for "+operation);
   check(delayed.get().execute(new ChatClient.ToolCall("read-after-stop","list_dir",Json.obj("path",root.toString()))).isError,"cancelled executor rejects subsequent calls");
  }
  Path moving=root.resolve("move.pdf");Files.writeString(moving,"move drawing");var moved=t.execute(new ChatClient.ToolCall("move","move_path",Json.obj("source",moving.toString(),"destination",container.toString())));check(!moved.isError&&!Files.exists(moving)&&Files.readString(container.resolve("move.pdf")).equals("move drawing"),"ordinary move semantics retained");
  check(copy(t,tree,tree.resolve("inside"),false).isError,"copy into source tree refused");String unc="\\\\synthetic-host.invalid\\share\\drawings";check(PathMap.none().path(unc).equals(unc)&&Path.of(unc).isAbsolute(),"UNC remains absolute without connecting to a network");
  try(var walk=Files.walk(root)){check(walk.noneMatch(p->p.getFileName().toString().startsWith(".localchat-copy-")),"owned staging files cleaned after copy");}
  System.out.println("PASS: "+checks+" verified copy/resume checks; synthetic local files, no network or inference");
 }
}
